insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('TG', 'TG-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2019-01-01', null, 'Code général des impôts, art. 196 — droit à déduction de la taxe qui grève les éléments du prix d''une opération imposable ; art. 199 — le droit à déduction s''exerce dans le mois de comptabilisation de la facture ; art. 201 — facture conforme à l''art. 64 du Livre des procédures fiscales. Bordereau Mod TVA 2016, case 18 « Déductions sur les biens et services excepté les immobilisations », alimentée par le cadre VII.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2019-01-01', null, 'Code général des impôts, art. 196-2 — déduction de la taxe figurant sur les factures d''achat de biens meubles ou immeubles inscrits à l''actif du bilan et affectés à des opérations taxables ; art. 199 — déduction dans le mois de comptabilisation de la facture, comme pour un bien qui n''est pas une immobilisation ; art. 202 — régularisations en cas de cession ou de changement d''affectation. Bordereau Mod TVA 2016, case 19 « Déductions sur les immobilisations », alimentée par le cadre VIII.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-P-18-ND', 'Achat 18 % non déductible (art. 197)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2019-01-01', null, 'Code général des impôts, art. 197 — sont exclus du droit à déduction, même affectés à une opération qui ouvre droit à déduction : 1° les voitures de tourisme et leurs pièces (sauf véhicules utilitaires, crédit-bail chez le crédit-bailleur, auto-école, transport de la clientèle hôtelière, transport public de personnes) ; 2° les dépenses de logement des dirigeants et du personnel, de réception, de restaurant, de spectacles et de déplacement (sauf transport sous contrat permanent et besoins collectifs du personnel sur le lieu de travail) ; 3° le mobilier et le matériel de logement ; 4° les objets non strictement indispensables à l''activité ; 5° les biens cédés et services rendus gratuitement ou à prix très inférieur au prix de revient, sauf objets publicitaires de moins de 5 000 F CFA HT ; 6° les services se rapportant à des biens exclus ; 7° les frais de carburant pour véhicules. La taxe est une part du coût de ce qui a été acheté.', 'S', null, 150, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2019-01-01', null, 'Code général des impôts, art. 196 pour le droit à déduction ; art. 199, dernier alinéa — pour les prestations de services et les travaux immobiliers, ce droit s''exerce dans le mois du paiement et non dans celui de la facture, à la différence des achats de biens (ligne au-dessus). Le pack ne porte pas cette nuance dans les écritures — il n''y a pas, côté achat, de compte de taxe en instance de paiement comme il y en a un côté vente (4432) — et se contente de la dire ici : voir le README. Bordereau Mod TVA 2016, même case 18 que les achats de biens.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-P-IMP-18', 'Importation 18 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'import', date '2019-01-01', null, 'Code général des impôts, art. 175-1 — les importations sont soumises à la TVA, l''importation s''entendant du franchissement du cordon douanier ; art. 182-2 — le fait générateur est la mise à la consommation au Togo au sens douanier ; art. 194 — la taxe est liquidée au cordon douanier lors du fait générateur ; art. 201 — la taxe déductible à l''importation est celle qui a été perçue à l''importation, justifiée par la déclaration douanière désignant l''assujetti comme destinataire réel. Bordereau Mod TVA 2016, cadre VII — une ligne par document douanier, déduction reportée sur la case 18.', null, null, 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-P-NR-18', 'Services d''un prestataire non établi au Togo, TVA due par le preneur', '{}'::jsonb, null, 'percent', 18, 'purchase', 'foreign_services_received', date '2019-01-01', null, 'Code général des impôts, art. 185 — une entreprise établie ou domiciliée hors du Togo qui y effectue une prestation de service dont le lieu d''imposition se situe au Togo (art. 182 à 184) supporte la même imposition qu''une entreprise togolaise ; à défaut de représentant fiscal accrédité, la taxe et les pénalités sont liquidées et acquittées par le destinataire de l''opération. Art. 183 — le lieu d''imposition d''une prestation de service est celui de son exécution ou, si elle est utilisée ailleurs, celui de son utilisation. La taxe due pour le compte du prestataire étranger attend son reversement au compte 4478 ; sa déduction chez le preneur suit le régime général de l''art. 196, reportée sur la case 18 comme un autre service.', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens meubles au taux normal, TVA au compte 4431', 'percent', 18, 'sale', 'domestic', date '2019-01-01', null, 'Code général des impôts, art. 195 — taux unique de 18 % applicable à toutes les activités et à tous les produits, sauf exonération de l''art. 180 ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 %. Art. 190 — le fait générateur d''une livraison de bien meuble est la délivrance du bien ; art. 191-1 — l''exigibilité intervient au même moment. Bordereau Mod TVA 2016, case 7 « au taux de 18 % (excepté livraison à soi-même) » et case 13 « au taux de 18 % [ligne 7*18%] ».', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-S-18-SRV', 'Prestations de services 18 %, exigibles à l''encaissement', '{}'::jsonb, 'Prestations de services et travaux immobiliers au taux normal, taxe exigible à l''encaissement', 'percent', 18, 'sale', 'domestic', date '2019-01-01', null, 'Code général des impôts, art. 195 pour le taux ; art. 190 — le fait générateur d''une prestation de service ou de travaux immobiliers est l''exécution du service ou des travaux ; art. 191-2 — l''exigibilité intervient lors de l''encaissement des acomptes, du prix ou de la rémunération, sauf option pour les débits accordée par le Commissaire des impôts, option qui ne peut avoir pour effet de payer la taxe après l''encaissement ; art. 199, dernier alinéa — le droit à déduction du client s''exerce, pour les services, dans le mois du paiement et non dans celui de la facture. Facturée, la taxe attend l''encaissement au compte 4432 « T.V.A. facturée sur prestations de services » ; encaissée, elle est exigible et passe au compte 4431 « sur ventes », dont l''intitulé couvre aussi les ventes de services : le plan n''a pas de compte de taxe en attente distinct. Bordereau Mod TVA 2016 : même case 7/13 que les biens, le formulaire ne distingue pas biens et services.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '4432', 'cgi', null, null, null, null),
  ('TG', 'TG-S-EXO', 'Opération exonérée (art. 180)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2019-01-01', null, 'Code général des impôts, art. 180 — opérations exonérées de la TVA parce que soumises à un autre impôt (I), agricoles (II), de profession libérale (III, dont les soins médicaux et hospitaliers, l''enseignement, les journaux hors publicité, les œuvres d''art vendues par leur auteur), d''organismes d''utilité générale (IV) ou listées à l''annexe TVA (V) ; bordereau Mod TVA 2016, case 3 « Exonérées », comptée dans les opérations non taxables (case 2) et non dans le chiffre d''affaires taxable.', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-S-EXP', 'Exportations et produits assimilés 0 %', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2019-01-01', null, 'Code général des impôts, art. 181-1 — exonération des exportations de biens et des services assimilés à des exportations, avec droit à déduction de la taxe acquittée auprès des fournisseurs (art. 181, dernier alinéa du I, et art. 196) ; bordereau Mod TVA 2016, case 10 « exportations et produits assimilés » au taux de 0 %, comptée dans les opérations taxables (case 6 = 7+8+9+10) et non dans les opérations non taxables — à la différence de la case 5 « exportations de produits non taxables », qui reste hors du champ de ce pack faute d''article trouvé qui distingue les deux cases (voir README).', 'G', null, 40, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('TG', 'TG-S-MP-18', 'Marchés publics payés par chèque du Trésor 18 %', '{}'::jsonb, 'Opérations afférentes aux marchés publics réglées par chèque du Trésor', 'percent', 18, 'sale', 'domestic', date '2019-01-01', null, 'Bordereau Mod TVA 2016, case 8 « afférente aux marchés publics avec Chèque Trésor » et case 14 « au taux de 18 % [ligne 8*18%] » — une case séparée de la case 7, au même taux de 18 % de l''art. 195. Aucun article du Code général des impôts ou du Livre des procédures fiscales consulté ne fonde un régime de TVA distinct pour ces opérations (ni retenue, ni assiette différente) : cette taxe reproduit le taux normal, seule la case déclarative change, parce que le formulaire officiel l''exige.', 'S', null, 30, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'bordereau', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

