insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('TG', 'TG-TVA', 'Déclaration de TVA (Taxe sur la Valeur Ajoutée)', array['month']::declaration_period[], null, date '2016-01-01', null, 'Livre des procédures fiscales, art. 60 — tout redevable de la TVA souscrit au plus tard le 15 de chaque mois, au titre du mois précédent, une déclaration conforme au modèle prescrit, obligatoire même sans opération imposable. Le modèle prescrit est le bordereau Mod TVA 2016, réf. OTR/PrF-Dpl/Bdr/001 (source « bordereau »), dont les cases numérotées 1 à 27 sont reprises ici ; les cadres VII, VIII et IX (cases 28, 29 et le détail de la case 4) sont des annexes justificatives qui ne portent pas de montant propre à la déclaration et ne sont pas reprises.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Livre des procédures fiscales, art. 60 — déclaration au plus tard le 15 de chaque mois au titre du mois précédent ; le bordereau Mod TVA 2016 porte la même mention « à souscrire au plus tard le 15 du mois ».', 'cgi', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('TG', 'TG-TVA', '1', 'total', 'Total chiffre d''affaires hors TVA', '{}'::jsonb, 10, null, array['2', '6']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, cadre II « TOTAL CHIFFRE D''AFFAIRES HORS TVA [lignes 2 + 6] », case 1.', 'bordereau'),
  ('TG', 'TG-TVA', '2', 'total', 'Opérations non taxables', '{}'::jsonb, 20, null, array['3', '4', '5']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 2 « Opérations non taxables », qui regroupe visuellement les cases 3, 4 et 5 sous son intitulé, de la même façon que la case 6 regroupe les cases 7 à 10 et porte, elle, une formule imprimée. Le formulaire n''imprime aucune formule pour la case 2 : cette lecture en est la somme, non un chiffre que le formulaire calcule lui-même.', 'bordereau'),
  ('TG', 'TG-TVA', '3', 'base', 'Exonérées', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 3 « Exonérées » ; Code général des impôts, art. 180.', 'cgi'),
  ('TG', 'TG-TVA', '4', 'base', 'Non imposées (sur la base d''attestations d''exonération)', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 4 « Non imposées (sur la base d''attestations d''exonération), voir IX », détaillée au cadre IX par attestation. Aucune taxe de ce pack n''alimente cette case : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '5', 'base', 'Exportations de produits non taxables', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 5 « Exportations de produits non taxables », comptée hors du chiffre d''affaires taxable (case 6), à la différence de la case 10 « exportations et produits assimilés » qui, elle, en fait partie. Aucun article trouvé ne distingue les deux ; aucune taxe de ce pack n''alimente cette case : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '6', 'total', 'Opérations taxables', '{}'::jsonb, 60, null, array['7', '8', '9', '10']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 6 « Opérations taxables [lignes 7 + 8 + 9 + 10] ».', 'bordereau'),
  ('TG', 'TG-TVA', '7', 'base', 'Au taux de 18 % (excepté livraison à soi-même)', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 7 ; Code général des impôts, art. 195.', 'cgi'),
  ('TG', 'TG-TVA', '8', 'base', 'Afférente aux marchés publics avec Chèque Trésor', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 8.', 'bordereau'),
  ('TG', 'TG-TVA', '9', 'base', 'Livraison à soi-même (L.A.S.M)', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 9 ; Code général des impôts, art. 175-2, art. 190 et art. 191-4. Aucune taxe de ce pack n''alimente cette case, faute d''un document du socle pour une opération sans contrepartie externe : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '10', 'base', 'Exportations et produits assimilés', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 10, au taux de 0 % ; Code général des impôts, art. 181-1.', 'cgi'),
  ('TG', 'TG-TVA', '11', 'total', 'TVA brute', '{}'::jsonb, 110, null, array['12']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, cadre III « TVA BRUTE [ligne 12] », case 11 : un doublon d''affichage de la case 12, placé en haut du formulaire à côté du chiffre d''affaires de la case 1.', 'bordereau'),
  ('TG', 'TG-TVA', '12', 'total', 'Total de la taxe collectée', '{}'::jsonb, 120, null, array['13', '14', '15']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 12 « lignes 13 + 14 + 15 ». La case 10 (exportations à 0 %) n''y entre pas : le formulaire l''annote « [ligne 10*0%] » sans lui donner de case de taxe.', 'bordereau'),
  ('TG', 'TG-TVA', '13', 'tax', 'Taxe exigible au taux de 18 %', '{}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 13 « au taux de 18 % [ligne 7*18%] ». Les écritures somment la taxe facturée document par document, calculée au même taux, plutôt que de recalculer 18 % de la case 7 en une fois : l''arrondi à la dizaine de francs de l''art. 194 du Code général des impôts se fait facture par facture et non sur le total.', 'bordereau'),
  ('TG', 'TG-TVA', '14', 'tax', 'Taxe sur les marchés publics avec Chèque Trésor', '{}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 14 « au taux de 18 % [ligne 8*18%] ».', 'bordereau'),
  ('TG', 'TG-TVA', '15', 'tax', 'Taxe sur les livraisons à soi-même', '{}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 15 « livraison à soi-même [ligne 9*18%] ». Aucune taxe de ce pack n''alimente cette case : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '16', 'total', 'Total TVA déductible', '{}'::jsonb, 160, null, array['17', '18', '19', '21']::text[], array['20']::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, cadre IV « TOTAL TVA DEDUCTIBLE [lignes 17+18+19-20+21] », case 16, reprise telle qu''imprimée.', 'bordereau'),
  ('TG', 'TG-TVA', '17', 'tax', 'Crédit de TVA reporté du mois précédent', '{}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 17. Le cœur ne reporte pas automatiquement d''une déclaration à l''autre le crédit de la case 27 de la période précédente : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '18', 'tax', 'Déductions sur les biens et services excepté les immobilisations', '{}'::jsonb, 180, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 18, alimentée par le cadre VII (case 28).', 'bordereau'),
  ('TG', 'TG-TVA', '19', 'tax', 'Déductions sur les immobilisations', '{}'::jsonb, 190, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 19, alimentée par le cadre VIII (case 29).', 'bordereau'),
  ('TG', 'TG-TVA', '20', 'tax', 'Complément de déduction demandé', '{}'::jsonb, 200, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 20, sur pièces justificatives. Une régularisation manuelle que le cœur ne calcule pas : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '21', 'tax', 'Reversement à effectuer', '{}'::jsonb, 210, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 21, sur pièces justificatives ; Code général des impôts, art. 202 — régularisations de la taxe déduite. Une régularisation manuelle que le cœur ne calcule pas : voir le README.', 'bordereau'),
  ('TG', 'TG-TVA', '23', 'total', 'TVA nette', '{}'::jsonb, 220, null, array['24']::text[], array['25']::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, cadre V « TVA NETTE [lignes 24 - 25] », case 23.', 'bordereau'),
  ('TG', 'TG-TVA', '24', 'total', 'TVA brute (report)', '{}'::jsonb, 230, null, array['12']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 24, imprimée « TVA brute (ligne 15) ». La ligne 15 n''est que la taxe sur les livraisons à soi-même, une des trois composantes de la TVA brute (case 12 = 13+14+15) : elle ne peut pas, seule, être la TVA brute totale que le cadre V reporte. Ce pack lit la case 24 comme un report de la case 12, cohérent avec le cadre III, et note l''incohérence d''impression plutôt que de la reproduire.', 'bordereau'),
  ('TG', 'TG-TVA', '25', 'total', 'TVA déductible (report)', '{}'::jsonb, 240, null, array['16']::text[], '{}'::text[], null, null, false, false, null, 'Bordereau Mod TVA 2016, case 25, imprimée « TVA déductible (ligne 16) ».', 'bordereau'),
  ('TG', 'TG-TVA', '26', 'total', 'TVA nette à payer', '{}'::jsonb, 250, null, array['24']::text[], array['25']::text[], null, null, true, false, null, 'Bordereau Mod TVA 2016, cadre V, case 26 « TVA nette à payer (lignes 24 - 25) ».', 'bordereau'),
  ('TG', 'TG-TVA', '27', 'total', 'Crédit à reporter', '{}'::jsonb, 260, null, array['25']::text[], array['24']::text[], null, null, true, false, null, 'Bordereau Mod TVA 2016, cadre V, case 27 « Crédit à reporter (lignes 25 - 24) ».', 'bordereau')
