update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Livre des procédures fiscales, art. 64 — la facture normalisée porte « le numéro de facture dans une série ininterrompue ». Le texte impose l''unicité et la continuité, jamais une forme ni une remise à zéro annuelle, que le format proposé ici permet sans l''exiger.',
  numbering_source_key          = 'cgi',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Code général des impôts, art. 190 — le fait générateur est, pour un bien meuble, la délivrance du bien, pour une importation, la mise à la consommation, pour une prestation de service ou des travaux immobiliers, l''exécution du service ou des travaux, et pour une livraison à soi-même, la première utilisation ; art. 191 — l''exigibilité intervient, pour les biens et les importations, lors du fait générateur lui-même (delivery_date dit cette règle), mais pour les prestations de services et les travaux immobiliers, lors de l''encaissement des acomptes, du prix ou de la rémunération, sauf option pour les débits autorisée par le Commissaire des impôts (art. 191-2). Cette seconde règle est portée par les taxes de service de ce pack, en cash_basis, et non par un second fait générateur du pays.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'La loi de finances 2026 aurait introduit une facture électronique certifiée (FEC) pour les opérations entre assujettis, par un nouvel article 62 du Livre des procédures fiscales et un arrêté n° 029/MFB/CAB/UPF du 19/02/2026, connus uniquement par des sources secondaires (patronat, presse économique) : ni le texte de la loi de finances 2026, ni celui de l''arrêté, ni la nouvelle rédaction de l''art. 62 du LPF n''ont été lus. Le Code général des impôts mis à jour 2025 cité dans ce registre (source « cgi ») ne porte que la facture normalisée à vignette de l''art. 64 du LPF, obligatoire (arrêté du ministre chargé des finances pour ses conditions d''édition et de gestion, liste annuelle des entreprises autorisées à s''auto-éditer) et sans profil structuré : le profil, la date d''obligation et les identifiants restent vides tant que le texte de la FEC n''a pas été lu.',
  einvoice_source_key           = 'cgi',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'TG';

